        //Session Timeout
        var t;
        var p;
        window.onload = resetTimer;
        document.onkeypress = resetTimer;
        document.onclick = resetTimer;

        function ShowTimeoutModal() {
            if ($('#btnSignIn').text() !== "Sign Up/In" && $('#overlay').is(":hidden")) {
                var notificationModal = new bootstrap.Modal('#timeoutModal');
                notificationModal.show();
            }
        }

        function SignOut() {
            document.getElementById('ddiSignOut').click();
        }

        function resetTimer() {
            clearTimeout(t);
            clearTimeout(p);
            p = setTimeout(ShowTimeoutModal, 600000);
            t = setTimeout(logout, 900000);
        }

        function refreshSessionAndResetTimer() {            

            if (isLoggedIn === true) {
                resetTimer();

                fetch('/Home/RefreshSession', {
                    method: 'GET'
                });
            }
            else{
                showErrorModal("Session Expired, login again.");
            }
        }

        function logout() {
            if ($('#btnSignIn').text() !== "Sign Up/In") {
                SignOut();
            }
        }

        $("input[type=text]").keyup(function () {
            $(this).val($(this).val().toUpperCase());
        });

        function showErrorModal(message) {
            $('#errorModal').find('.modal-body').text(message);
            $('#errorModal').modal('show');
        }

        // On document ready
        $(document).ready(function () {
            $("input[type=text]").keyup(function () {
                $(this).val($(this).val().toUpperCase());
            });
            function showAlert(message, type) {
                var alertContainer = $('#alertContainer');
                var alertMessage = $('#alertMessage');

                alertMessage.removeClass().addClass('alert alert-dismissible fade show').addClass('alert-' + type);
                $('#alertText').text(message);

                alertContainer.show();

                setTimeout(function () {
                    alertContainer.fadeOut();
                }, 3000);
            }
            window.showAlert = showAlert;

            $(".nav-link").on('click', function (event) {
                if (!$(this).text().includes("Feedback")) {
                    $("#overlay").show();
                }
            });

            // Automatic timeout after 15 min
            resetTimer();
        });

        // On form submission
        $(document).on('submit', function () {
            $("#overlay").show();
        });

        // On page unload (navigating to another page)
        $(window).on('beforeunload', function () {
            $("#overlay").show();
        });

        // On page unload (navigating to another page)
        $(window).on('load', function () {
            $("#overlay").hide();
        });

        window.addEventListener('pageshow', function () {
            $("#overlay").hide(); // runs even on BFCache restore
        });

     
 
 
     

         
             
                 
                 
                     
                 
                 
                     
                         
                             
